// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.roll(blockNum);

        vm.warp(1);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback reverted unexpectedly");

        bool shouldBeZero = (blockNum % 15 == 0);
        uint256 balance = address(c).balance;
        bool actuallyZero = (balance == 0);

        assertTrue(actuallyZero == shouldBeZero);
    }
}
